import Foundation

/// Fast structural screening for captions generated by a multilingual LLM.
/// This is not a natural-language judge: a Japanese sentence can still be
/// nonsensical and therefore remains user-editable in storyboard review.
enum MangaJapaneseLettering {
    static func clean(_ input: String, fallback: String, limit: Int) -> String {
        let limit=max(0,limit)
        guard limit>0 else {return ""}
        let value=String(input
            .replacingOccurrences(of: "\n", with: " ")
            .replacingOccurrences(of: "\r", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .prefix(limit))
        guard !value.isEmpty else {return String(fallback.prefix(limit))}
        let scalars=Array(value.unicodeScalars)
        let japanese=scalars.filter { s in
            (0x3040...0x30FF).contains(Int(s.value)) ||
            (0x3400...0x9FFF).contains(Int(s.value)) ||
            (0xFF66...0xFF9D).contains(Int(s.value))
        }.count
        let latin=scalars.filter { s in
            (0x0041...0x005A).contains(Int(s.value)) ||
            (0x0061...0x007A).contains(Int(s.value))
        }.count
        let control=scalars.contains { CharacterSet.controlCharacters.contains($0) }
        let replacement=scalars.contains { $0.value==0xFFFD }
        let markup=value.contains("</") || value.contains("<script") ||
                   value.contains("http://") || value.contains("https://")
        var run=0, previous: Unicode.Scalar?
        var excessivelyRepeated=false
        for scalar in scalars {
            if scalar==previous {run+=1} else {run=1;previous=scalar}
            if run>=7 {excessivelyRepeated=true;break}
        }
        guard japanese>0, latin<=max(6,japanese),
              !control, !replacement, !markup, !excessivelyRepeated else {
            return String(fallback.prefix(limit))
        }
        return value
    }
}